DELETE FROM sfi_result; PRAGMA main.cache_size=2000; PRAGMA temp.cache_size=2000; PRAGMA cache_spill=OFF; INSERT INTO sfi_result(seq,value) SELECT 1,cache_spill FROM pragma_cache_spill UNION ALL SELECT 2,cache_spill FROM pragma_cache_spill('main') UNION ALL SELECT 3,cache_spill FROM pragma_cache_spill('temp');